const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const create_button = require('button')
const btc_input_card = require('btc_input_card')
const input_field = require('input_field')
const templates = require('templates')
const create_invoice_confirmation = require('create_invoice_confirmation')

module.exports = create_invoice

async function create_invoice(opts = {}, callbacks = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const onCreateFn = callbacks.onCreate || null
  const onCloseFn = callbacks.onClose || null

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
    <div class="create-invoice-container">
      <div class="create-invoice-header">  
        <div class="title-container"> 
          <div class="create-invoice-header">Create Lightning Invoice</div>
          <div class="btc-icon"></div>
        </div>  
        <div class="x-icon"></div>
      </div>
      <div class="scroll-area">
        <div class="btc-input-card"></div>
        <div class="extra-input1"></div>
        <div class="extra-input2"></div>
        <div class="divider"></div>
        <div class="templates-heading">Use Templates</div>
        <div class="template1"></div>
        <div class="template2"></div>
        <div class="template3"></div>
      </div>
      <div class="create_button"></div>
      <div class="create-status" style="text-align:center; font-size: 0.9em; margin-top: 10px; min-height: 20px;"></div>
    </div>
    <div class="confirmation-container hidden"></div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const create_button_component = shadow.querySelector('.create_button')
  const btc_input_card_component = shadow.querySelector('.btc-input-card')
  const input1_component = shadow.querySelector('.extra-input1')
  const input2_component = shadow.querySelector('.extra-input2')
  const template1_container = shadow.querySelector('.template1')
  const template2_container = shadow.querySelector('.template2')
  const template3_container = shadow.querySelector('.template3')
  const confirmation_container = shadow.querySelector('.confirmation-container')
  const status_el = shadow.querySelector('.create-status')

  const subs = await sdb.watch(onbatch)

  const button_component = await create_button(subs[0])
  const btc_component = await btc_input_card(subs[1])
  const input1 = await input_field(subs[2])
  const input2 = await input_field(subs[3])
  const templates_component1 = await templates(subs[4])
  const templates_component2 = await templates(subs[5])
  const templates_component3 = await templates(subs[6])


  create_button_component.append(button_component)
  btc_input_card_component.append(btc_component)
  input1_component.append(input1)
  input2_component.append(input2)
  template1_container.append(templates_component1)
  template2_container.append(templates_component2)
  template3_container.append(templates_component3)

  let invoice_mounted = false
  let confirm_el = null

  const closeBtn = shadow.querySelector('.x-icon')
  if (closeBtn) {
    closeBtn.onclick = () => {
      if (onCloseFn) onCloseFn()
      const dropdown = el.parentNode
      if (dropdown) {
        dropdown.classList.add('hidden')
      }
    }
  }

  button_component.addEventListener('click', async () => {
    const amount_btc = btc_component.getAmount ? btc_component.getAmount() : 0
    const description = input2.getValue ? input2.getValue().trim() : ''

    if (!amount_btc || parseFloat(amount_btc) <= 0) {
      status_el.textContent = '❌ Please enter a valid amount'
      status_el.style.color = 'red'
      return
    }

    if (!description) {
      status_el.textContent = '❌ Please enter a description'
      status_el.style.color = 'red'
      return
    }

    status_el.textContent = '⏳ Creating invoice...'
    status_el.style.color = '#555'

    if (onCreateFn) onCreateFn({ amount_btc, description })
  })

  // Allow the parent (lightning_buttons) to push real LN balance into the btc_input_card
  el.updateBalance = function (balance) {
    if (btc_component && typeof btc_component.updateBalance === 'function') {
      btc_component.updateBalance(balance)
    }
  }

  // Reset all form state 
  el.reset = function () {
    if (btc_component && typeof btc_component.setAmount === 'function') {
      btc_component.setAmount(0)
    }
    if (input2 && typeof input2.clear === 'function') {
      input2.clear()
    }
    status_el.textContent = ''
    status_el.style.color = ''
    confirmation_container.classList.add('hidden')
  }

  // Populate the 3 template slots with real LN active requests from the backend
  el.updateTemplates = function (templates) {
    const slots = [
      { container: template1_container, component: templates_component1 },
      { container: template2_container, component: templates_component2 },
      { container: template3_container, component: templates_component3 },
    ]

    slots.forEach(function (slot, i) {
      const tpl = templates[i]
      if (!tpl) {
        // No data for this slot — hide it
        slot.container.style.display = 'none'
        return
      }
      slot.container.style.display = ''
      // amount from backend is in sats — convert to BTC for display
      const amtBtc = (tpl.amount || 0) / 100000000
      const label = tpl.description || ''
      if (slot.component && typeof slot.component._update === 'function') {
        slot.component._update({}, amtBtc, label)
      }
      // Wire click to pre-fill form fields
      slot.container.onclick = function () {
        if (btc_component && typeof btc_component.setAmount === 'function') {
          btc_component.setAmount(amtBtc)
        }
        if (input2 && typeof input2.setValue === 'function') {
          input2.setValue(label)
        }
        status_el.textContent = ''
        status_el.style.color = ''
      }
    })
  }

  el.onCreated = async function (data) {
    if (data && data.error) {
      status_el.textContent = '❌ ' + (data.error || 'Failed to create invoice')
      status_el.style.color = 'red'
      return
    }

    status_el.textContent = '✅ Invoice created!'
    status_el.style.color = 'green'
    confirmation_container.classList.remove('hidden')

    if (!invoice_mounted) {
      confirm_el = await create_invoice_confirmation(subs[7], {
        onClose: () => confirmation_container.classList.add('hidden')
      })
      confirmation_container.append(confirm_el)
      invoice_mounted = true
    }

    if (confirm_el && typeof confirm_el.updateInvoiceData === 'function') {
      confirm_el.updateInvoiceData(data)
    }
  }

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data

    const btc_icon = shadow.querySelector('.btc-icon')
    const x_icon = shadow.querySelector('.x-icon')

    btc_icon.innerHTML = dricons[0]
    x_icon.innerHTML = dricons[1]
  }

  async function ondata(data) {

  }
}

function fallback_module() {
  return {
    api,
    _: {
      'button': { $: '' },
      'btc_input_card': { $: '' },
      'input_field': { $: '' },
      'templates': { $: '' },
      'create_invoice_confirmation': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const button = {
      mapping: {
        style: 'style',
        data: 'data',
      },
      0: {
        label: 'Create Invoice'
      }
    }

    const btc_input_card = {
      mapping: {
        style: 'style',
        data: 'data',
      },
      1: {
        balance: 0.0024,
      }
    }

    const input_field = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      2: {
        placeholder: 'Enter invoice title',
      },
      3: {
        placeholder: 'Enter invoice note'
      }

    }

    const templates = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      4: {
        date: "2025-05-10",
        btc: 0.012,
        usd: 200
      },
      5: {
        date: "2024-12-25",
        btc: 0.005,
        usd: 80
      },
      6: {
        date: "2024-01-01",
        btc: 0.01,
        usd: 150
      }
    }

    const create_invoice_confirmation = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      7: {
        value: [
          { label: "Label", value: "Work Payment" },
          { label: "Note", value: "This is the month of may invoice and i also updated everything too" },
          { label: "Amount", value: "0.0020 BTC", icon: "lightning.svg", convert: true }
        ]
      },
    }

    return {
      drive: {
        'icons/': {
          'lightning.svg': {
            '$ref': 'lightning.svg'
          },
          'x.svg': {
            '$ref': 'x.svg'
          },
        },
        'style/': {
          'create_invoice.css': {
            '$ref': 'create_invoice.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        button,
        btc_input_card,
        input_field,
        templates,
        create_invoice_confirmation
      }
    }
  }
}
